#[inductive(update_done)]
fn update_done_inductive(pre: Self, post: Self, rid: ReqId) {
    // The transition changes an UpdateState from Applied { ret, idx } to Done { ret, idx }
    // We need to show that all invariants are preserved.

    // First, let's establish what we know from the transition:
    // 1. pre.local_updates.contains_key(rid) and pre.local_updates[rid].is_Applied()
    // 2. pre.version_upper_bound > idx (from the require clause)
    // 3. post.local_updates[rid] == UpdateState::Done { ret, idx }
    // 4. post.local_updates.remove(rid) == pre.local_updates.remove(rid)

    // Show that the local_updates invariant is preserved
    assert forall |r| #[trigger] post.local_updates.contains_key(r) implies post.inv_local_updates_wf(post.local_updates[r]) by {
        if r == rid {
            // For the changed entry, we need to show it satisfies the Done case
            let UpdateState::Done { ret, idx } = post.local_updates[r];
            // We know pre.local_updates[r].is_Applied() and pre.local_updates[r] == UpdateState::Applied { ret, idx }
            // From the invariant on pre, we have pre.inv_local_updates_wf(pre.local_updates[r])
            // This means idx < pre.tail (from Applied case)
            // We also know from the transition that pre.version_upper_bound > idx
            // Therefore idx < post.version_upper_bound, which satisfies the Done case
            assert(idx < post.version_upper_bound);
        } else {
            // For unchanged entries, the invariant is preserved from pre
            assert(post.local_updates[r] == pre.local_updates[r]);
            assert(pre.inv_local_updates_wf(pre.local_updates[r]));
            // Need to show post.inv_local_updates_wf(post.local_updates[r])
            // Since post.local_updates[r] == pre.local_updates[r], and the invariant formula
            // only refers to self.log, self.tail, self.version_upper_bound, which are unchanged
            // except for version_upper_bound which can only increase, the invariant is preserved
            assert(post.inv_local_updates_wf(post.local_updates[r]));
        }
    }

    // Show that other invariants are preserved
    // Most invariants don't depend on local_updates directly, or are preserved because
    // local_updates only changed in one entry

    // The update_results_match invariant:
    assert forall |r| #[trigger] post.local_updates.contains_key(r) implies post.update_results_match(post.local_updates[r]) by {
        if r == rid {
            // For the changed entry from Applied to Done, the result should be the same
            let UpdateState::Done { ret, idx } = post.local_updates[r];
            assert(ret == DT::dispatch_mut_spec(compute_nrstate_at_version(post.log, idx), post.log[idx].op).1);
        } else {
            // For unchanged entries, the invariant is preserved from pre
            assert(post.update_results_match(post.local_updates[r]));
        }
    }

    // For combiner-related invariants, we need to show that changing one local_updates entry
    // from Applied to Done preserves the well-formedness conditions
    assert forall |node_id| #[trigger] post.combiner.contains_key(node_id) implies post.wf_combiner_for_node_id(node_id) by {
        // The combiner state itself hasn't changed, only local_updates changed for one rid
        // We need to check that LogRangeMatchesQueue and related predicates are preserved
        match post.combiner[node_id] {
            CombinerState::Placed { queued_ops } => {
                // Uses LogRangeMatchesQueue with idx=0
                // Uses QueueRidsUpdatePlaced with idx=0 and QueueRidsUpdateDone with idx=0
                // Since our rid may or may not be in queued_ops, we need to check both cases
                if queued_ops.contains(rid) {
                    // The lemmas like LogRangeMatchesQueue_update_change should handle this
                    LogRangeMatchesQueue_update_change(queued_ops, post.log, 0, post.local_versions[node_id], post.tail, node_id, pre.local_updates, post.local_updates);
                    QueueRidsUpdatePlaced_update_change(queued_ops, pre.local_updates, post.local_updates, 0);
                } else {
                    // No change to the queue, so no change to the properties
                }
            }
            CombinerState::LoadedLocalVersion{ queued_ops, lversion } => {
                if queued_ops.contains(rid) {
                    LogRangeMatchesQueue_update_change(queued_ops, post.log, 0, lversion, post.tail, node_id, pre.local_updates, post.local_updates);
                    QueueRidsUpdatePlaced_update_change(queued_ops, pre.local_updates, post.local_updates, 0);
                }
            }
            CombinerState::Loop{ queued_ops, idx, lversion, tail } => {
                if queued_ops.contains(rid) {
                    if idx <= queued_ops.index_of(rid) {
                        LogRangeMatchesQueue_update_change(queued_ops, post.log, idx, lversion, tail, node_id, pre.local_updates, post.local_updates);
                        QueueRidsUpdatePlaced_update_change_idx(queued_ops, pre.local_updates, post.local_updates, idx);
                        QueueRidsUpdateDone_update_change_idx(queued_ops, pre.local_updates, post.local_updates, idx);
                    }
                }
            }
            CombinerState::UpdatedVersion{ queued_ops, tail } => {
                if queued_ops.contains(rid) {
                    // For UpdatedVersion, we check QueueRidsUpdateDone with idx=queued_ops.len()
                    QueueRidsUpdateDone_update_change_full(queued_ops, pre.local_updates, post.local_updates);
                }
            }
            _ => {}
        }
    }
}

