#[inductive(update_done)]
fn update_done_inductive(pre: Self, post: Self, rid: ReqId) {
    // The transition changes local_updates[rid] from Applied to Done
    // We need to show that all invariants are preserved

    // Show combiner invariants are preserved
    assert forall |node_id| #[trigger] post.combiner.contains_key(node_id) implies post.wf_combiner_for_node_id(node_id) by {
        assert(post.combiner[node_id] == pre.combiner[node_id]);
        match post.combiner[node_id] {
            CombinerState::Placed { queued_ops } => {
                if queued_ops.contains(rid) {
                    LogRangeMatchesQueue_update_change(queued_ops, post.log, 0, post.local_versions[node_id], post.tail, node_id, pre.local_updates, post.local_updates);
                }
                assert(post.wf_combiner_for_node_id(node_id));
            }
            CombinerState::LoadedLocalVersion{ queued_ops, lversion } => {
                if queued_ops.contains(rid) {
                    LogRangeMatchesQueue_update_change(queued_ops, post.log, 0, lversion, post.tail, node_id, pre.local_updates, post.local_updates);
                }
                assert(post.wf_combiner_for_node_id(node_id));
            }
            CombinerState::Loop{ queued_ops, idx, lversion, tail } => {
                if queued_ops.contains(rid) && idx <= queued_ops.index_of(rid) {
                    LogRangeMatchesQueue_update_change(queued_ops, post.log, idx, lversion, tail, node_id, pre.local_updates, post.local_updates);
                }
                assert(post.wf_combiner_for_node_id(node_id));
            }
            CombinerState::UpdatedVersion{ queued_ops, tail } => {
                // For UpdatedVersion, we need to show QueueRidsUpdateDone(queued_ops, post.local_updates, queued_ops.len())
                // Since only one entry changed from Applied to Done, and QueueRidsUpdateDone allows both Applied and Done,
                // this should be preserved
                if queued_ops.contains(rid) {
                    // The specific lemma we'd need here doesn't exist, but we can argue directly:
                    // For all j in 0..queued_ops.len(), if post.local_updates.contains_key(queued_ops[j]), 
                    // then post.local_updates[queued_ops[j]] is either Applied or Done
                    assert forall |j| 0 <= j < queued_ops.len() implies 
                        post.local_updates.contains_key(#[trigger] queued_ops[j]) implies 
                        (post.local_updates[queued_ops[j]].is_Applied() || post.local_updates[queued_ops[j]].is_Done()) by {
                        if queued_ops[j] == rid {
                            // This is the one that changed - it's now Done
                            assert(post.local_updates[queued_ops[j]].is_Done());
                        } else {
                            // This didn't change - it was either Applied or Done before, so it still is
                            assert(post.local_updates[queued_ops[j]] == pre.local_updates[queued_ops[j]]);
                            assert(pre.local_updates[queued_ops[j]].is_Applied() || pre.local_updates[queued_ops[j]].is_Done());
                        }
                    }
                } else {
                    // rid not in queued_ops, so nothing changed for this combiner
                    assert(post.local_updates =~= pre.local_updates);
                }
                assert(post.wf_combiner_for_node_id(node_id));
            }
            CombinerState::Ready => {
                assert(post.wf_combiner_for_node_id(node_id));
            }
        }
    }
}

