                        assert(post.local_updates[queued_ops[j]] == pre.local_updates[queued_ops[j]]);
                        // From the pre invariant, we know this was either Applied or Done
                        assert(pre.local_updates[queued_ops[j]].is_Applied() || pre.local_updates[queued_ops[j]].is_Done());
