#[inductive(update_done)]
fn update_done_inductive(pre: Self, post: Self, rid: ReqId) {
    assert(post.combiner_states_wf()) by {
        assert forall |node_id| #[trigger] post.combiner.contains_key(node_id) implies post.wf_combiner_for_node_id(node_id) by {
            // The combiner state itself didn't change, only local_updates changed for one rid
            assert(post.combiner[node_id] == pre.combiner[node_id]);
            // Since pre satisfied the invariant and we only changed local_updates (not combiner),
            // most conditions should be preserved. The only tricky part is UpdatedVersion case
            // where QueueRidsUpdateDone is checked.
            match post.combiner[node_id] {
                CombinerState::UpdatedVersion{ queued_ops, tail } => {
                    // For UpdatedVersion, we need to show QueueRidsUpdateDone(queued_ops, post.local_updates, queued_ops.len())
                    // Since we only changed one entry from Applied to Done, and QueueRidsUpdateDone allows both,
                    // this should be preserved.
                }
                _ => {
                    // Other cases should be straightforward since they don't depend on the specific states
                    // of entries in local_updates in a way that would be affected by our change
                }
            }
        }
    }
}

