fn update_done_inductive(pre: Self, post: Self, rid: ReqId) {
    // The update_done transition only changes local_updates (changing one entry from Applied to Done)
    // and does not change combiner, log, tail, version_upper_bound, or local_versions.

    assert forall |node_id| #[trigger] post.combiner.contains_key(node_id) implies post.wf_combiner_for_node_id(node_id) by {
        // The combiner state is unchanged by update_done
        assert(post.combiner[node_id] == pre.combiner[node_id]);

        match post.combiner[node_id] {
            CombinerState::UpdatedVersion{ queued_ops, tail } => {
                // For UpdatedVersion, we need to show that all conditions still hold.
                // Most conditions don't depend on local_updates values, so they're preserved.
                // The only condition that depends on local_updates is QueueRidsUpdateDone.

                // Since pre satisfies the invariant, we know QueueRidsUpdateDone held for pre.local_updates
                // We need to show it still holds for post.local_updates
                assert(QueueRidsUpdateDone(queued_ops, post.local_updates, queued_ops.len())) by {
                    assert forall |j| 0 <= j < queued_ops.len() implies 
                        (#[trigger] post.local_updates.contains_key(queued_ops[j]) ==>
                            post.local_updates[queued_ops[j]].is_Applied() || post.local_updates[queued_ops[j]].is_Done()) by {
                        // Since pre satisfies the invariant:
                        assert(pre.local_updates.contains_key(queued_ops[j]) ==> 
                               (pre.local_updates[queued_ops[j]].is_Applied() || pre.local_updates[queued_ops[j]].is_Done()));

                        // Case analysis on whether queued_ops[j] equals rid:
                        if queued_ops[j] == rid {
                            // This entry was changed from Applied to Done
                            assert(post.local_updates[queued_ops[j]].is_Done());
                        } else {
                            // This entry is unchanged
                            assert(post.local_updates.contains_key(queued_ops[j]) == pre.local_updates.contains_key(queued_ops[j]));
                            assert(post.local_updates[queued_ops[j]] == pre.local_updates[queued_ops[j]]);
                            // So it still satisfies the condition
                        }
                    }
                }
                // Now that we've proven QueueRidsUpdateDone, all conditions for UpdatedVersion should hold
                assert(post.wf_combiner_for_node_id(node_id));
            }
            _ => {
                // For all other combiner states, the wf condition should be preserved
                // since they either don't depend on local_updates or depend on it in a way
                // that's preserved by changing one entry from Applied to Done.
                assert(post.wf_combiner_for_node_id(node_id));
            }
        }
    }
}

